function ActionDarkDreamMainRankCell:RefreshShow(data)
	CfUtils.SetActive(self.Empty.gameObject,isNull(data))
	CfUtils.SetActive(self.Content.gameObject,isNotNull(data))
	if isNotNull(data) then
		CfUtils.FillText(self.TextRank,"NO."..data.ranking)
		CfUtils.FillText(self.TextName,	data.name)
		---@type CommonPlayerHeadNode
		local env = CfUtils.GetLuaScr(self.CommonPlayerHeadNode, Constants.UILuaTablePath.ComPlayerHead)
		if env then
			env:FreshAvatarFrame(data.avatar, data.avatarFrame)
			env:SetCallBack(function()
				if checkNumber(data.playerId) > 0 then  -- 机器人不能点
					-- 直接进入个人信息界面2D版
					GameUtils.ShowPlayerInfo(data.playerId)
				end
			end)
		end
	end
end

function ActionDarkDreamMainRankCell:OnDestroy()
	self.controller = nil--luabehaviour 中CSharp对象
	self:Delete()
end

return ActionDarkDreamMainRankCell